import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine().trim();
        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        int k = Integer.parseInt(parts[1]);

        int[] adj = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            adj[i] = (i * k) % n;
        }

        int count = 0;

        for (int i = 1; i < n; i++) {
            if (!visited[i]) {
                traverse(i, adj, visited);
                count++;
            }
        }

        long MOD = 1000000007L;

        if (k == 1) {
            System.out.println(pow(n, n, MOD));
        } else {
            System.out.println(pow(n, count, MOD));
        }
        scanner.close();
    }

    private static void traverse(int node, int[] adj, boolean[] visited) {
        visited[node] = true;
        while (!visited[adj[node]]) {
            node = adj[node];
            visited[node] = true;
        }
    }

    private static long pow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
